_number integer, tribe_name text, contestants jsonb, episode_start integer, episode_end integer, challenge_wins numeric) WHERE r.season_number IS NULL OR r.season_number NOT IN (41, 42, 43, 44, 45, 46, 47, 48, 49) OR r.tribe_name IS NULL OR btrim(r.tribe_name) = '' OR r.episode_start IS NULL OR r.episode_end IS NULL OR r.episode_start < 1 OR r.episode_end < r.episode_start OR r.contestants IS NULL OR jsonb_typeof(r.contestants) <> 'array' OR r.challenge_wins < 0 OR r.challenge_wins <> trunc(r.challenge_wins) ) THEN RAISE EXCEPTION 'Invalid replacement row fields'; END IF; IF EXISTS ( SELECT 1 FROM jsonb_array_elements(replacements) AS e(v) WHERE jsonb_array_length(v->'contestants') = 0 OR (SELECT count(*) FROM jsonb_array_elements(v->'contestants')) <> (SELECT count(DISTINCT i) FROM jsonb_array_elements(v->'contestants') AS z(i)) OR EXISTS ( SELECT 1 FROM jsonb_array_elements(v->'contestants') AS z(i) WHERE jsonb_typeof(i) <> 'number' OR i::text !~ '^[1-9][0-9]*$') ) THEN RAISE EXCEPTION 'Empty roster, duplicate contestant, or non-integer ID'; END IF;   SELECT format('id=%s, season=%s, name=%s', e.id, e.season_number, e.contestant_name) INTO bad FROM jsonb_to_recordset(expected_lookup) AS e( id integer, season_number integer, contestant_name text) LEFT JOIN survivor_stats AS s ON s.id = e.id WHERE s.id IS NULL OR s.season_number IS DISTINCT FROM e.season_number OR s.contestant_name IS DISTINCT FROM e.contestant_name LIMIT 1; IF bad IS NOT NULL THEN RAISE EXCEPTION 'survivor_stats no longer matches the export: %', bad; END IF; IF EXISTS ( SELECT 1 FROM survivor_stats AS s WHERE s.season_number IN (41, 42, 43, 44, 45, 46, 47, 48, 49) AND NOT EXISTS ( SELECT 1 FROM jsonb_to_recordset(expected_lookup) AS e( id integer, season_number integer, contestant_name text) WHERE e.id = s.id AND e.season_number = s.season_number) ) THEN RAISE EXCEPTION 'survivor_stats contains additional appearances in replacement seasons'; END IF;  SELECT format('id=%s, row season=%s', i.id, r.season_number) INTO bad FROM jsonb_to_recordset(replacements) AS r( season_number integer, contestants jsonb) CROSS JOIN LATERAL ( SELECT value::integer AS id FROM jsonb_array_elements_text(r.contestants) ) AS i LEFT JOIN survivor_stats AS s ON s.id = i.id WHERE s.id IS NULL OR s.season_number IS DISTINCT FROM r.season_number OR NOT EXISTS ( SELECT 1 FROM jsonb_to_recordset(expected_lookup) AS e( id integer, season_number integer, contestant_name text) WHERE e.id = i.id AND e.season_number = r.season_number) LIMIT 1; IF bad IS NOT NULL THEN RAISE EXCEPTION 'Invalid or wrong-season contestant ID: %', bad; END IF;  IF EXISTS ( SELECT 1 FROM jsonb_array_elements(replacements) WITH ORDINALITY AS a(v, n) JOIN jsonb_array_elements(replacements) WITH ORDINALITY AS b(v, n) ON a.n < b.n AND a.v->>'season_number' = b.v->>'season_number' AND (a.v->>'episode_start')::integer <= (b.v->>'episode_end')::integer AND (b.v->>'episode_start')::integer <= (a.v->>'episode_end')::integer WHERE a.v->>'tribe_name' = b.v->>'tribe_name' OR EXISTS ( SELECT 1 FROM jsonb_array_elements(a.v->'contestants') AS ai(i) JOIN jsonb_array_elements(b.v->'contestants') AS bi(i) ON ai.i = bi.i) ) THEN RAISE EXCEPTION 'Overlapping tribe ranges or simultaneous contestant membership'; END IF;  IF EXISTS ( SELECT 1 FROM jsonb_to_recordset(coverage) AS c( season_number integer, expected_rows integer, episodes jsonb) WHERE c.expected_rows <> ( SELECT count(*) FROM jsonb_to_recordset(replacements) AS r(season_number integer) WHERE r.season_number = c.season_number) OR c.episodes <> ( SELECT jsonb_agg(g.ep ORDER BY g.ep) FROM ( SELECT DISTINCT gs.ep FROM jsonb_to_recordset(replacements) AS r( season_number integer, episode_start integer, episode_end integer) CROSS JOIN LATERAL generate_series(r.episode_start, r.episode_end) AS gs(ep) WHERE r.season_number = c.season_number ) AS g) ) THEN RAISE EXCEPTION 'Incomplete replacement season or unexpected episode coverage'; END IF; IF (SELECT count(DISTINCT season_number) FROM jsonb_to_recordset(coverage) AS c(season_number integer)) <> 9 OR EXISTS ( SELECT 1 FROM jsonb_to_recordset(replacements) AS r(season_number integer) WHERE NOT EXISTS ( SELECT 1 FROM jsonb_to_recordset(coverage) AS c(season_number integer) WHERE c.season_number = r.season_number)) THEN RAISE EXCEPTION 'Season manifest is inconsistent'; END IF;  DELETE FROM tribal_episodes WHERE season_number IN (41, 42, 43, 44, 45, 46, 47, 48, 49); INSERT INTO tribal_episodes ( season_number, tribe_name, contestants, episode_start, episode_end, challenge_wins ) SELECT r.season_number, r.tribe_name, ARRAY(SELECT value::integer FROM jsonb_array_elements_text(r.contestants)), r.episode_start, r.episode_end, r.challenge_wins FROM jsonb_to_recordset(replacements) AS r( season_number integer, tribe_name text, contestants jsonb, episode_start integer, episode_end integer, challenge_wins numeric) ORDER BY r.season_number, r.episode_start, r.tribe_name; GET DIAGNOSTICS inserted = ROW_COUNT; IF inserted <> 146 THEN RAISE EXCEPTION 'Inserted row count mismatch: %', inserted; END IF; END;$tribal_import$ LANGUAGE plpgsql; COMMIT;